import 'dart:async';
import 'dart:convert';
import 'package:web_socket_channel/web_socket_channel.dart';

class KerenSocketService {
  KerenSocketService(this.url);
  final Uri url;
  final _events = StreamController<Map<String, dynamic>>.broadcast();
  WebSocketChannel? _channel;
  StreamSubscription? _sub;
  Timer? _retryTimer;
  bool _closed = false;
  int _attempt = 0;

  Stream<Map<String, dynamic>> get events => _events.stream;

  void connect() {
    if (_closed || _channel != null) return;
    try {
      final ch = WebSocketChannel.connect(url);
      _channel = ch;
      _sub = ch.stream.listen((data) {
        _attempt = 0;
        final decoded = jsonDecode(data as String);
        if (decoded is Map<String, dynamic>) _events.add(decoded);
      }, onError: (_) => _reconnect(), onDone: _reconnect, cancelOnError: true);
    } catch (_) {
      _reconnect();
    }
  }

  void send(Map<String, dynamic> message) {
    final ch = _channel;
    if (ch == null) throw StateError('WebSocket not connected');
    ch.sink.add(jsonEncode(message));
  }

  void _reconnect() {
    _sub?.cancel();
    _sub = null;
    _channel?.sink.close();
    _channel = null;
    if (_closed || _retryTimer != null) return;
    final seconds = (1 << _attempt.clamp(0, 5));
    _attempt++;
    _retryTimer = Timer(Duration(seconds: seconds), () {
      _retryTimer = null;
      connect();
    });
  }

  Future<void> dispose() async {
    _closed = true;
    _retryTimer?.cancel();
    await _sub?.cancel();
    await _channel?.sink.close();
    await _events.close();
  }
}
