class EventDedupe {
  EventDedupe({this.ttl = const Duration(minutes: 5), this.maxSize = 1000});
  final Duration ttl;
  final int maxSize;
  final Map<String, DateTime> _seen = {};

  bool accept(String id, DateTime now) {
    _seen.removeWhere((_, t) => now.difference(t) > ttl);
    if (_seen.containsKey(id)) return false;
    if (_seen.length >= maxSize) {
      final oldest = _seen.entries.reduce((a, b) => a.value.isBefore(b.value) ? a : b).key;
      _seen.remove(oldest);
    }
    _seen[id] = now;
    return true;
  }
}
