class EventDedupe(
    private val ttlMs: Long = 300_000,
    private val maxSize: Int = 1000
) {
    private val seen = LinkedHashMap<String, Long>()

    @Synchronized
    fun accept(id: String, nowMs: Long = System.currentTimeMillis()): Boolean {
        val it = seen.entries.iterator()
        while (it.hasNext()) {
            if (nowMs - it.next().value > ttlMs) it.remove()
        }
        if (seen.containsKey(id)) return false
        if (seen.size >= maxSize) seen.entries.iterator().let { iter -> if (iter.hasNext()) { iter.next(); iter.remove() } }
        seen[id] = nowMs
        return true
    }
}
