from pydantic import BaseModel
import sqlite3, time

app = FastAPI()
DB = 'keren.db'

class Claim(BaseModel):
    worker_id: str

def conn():
    c = sqlite3.connect(DB, isolation_level=None)
    c.row_factory = sqlite3.Row
    c.execute('PRAGMA journal_mode=WAL')
    c.execute('CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,status TEXT NOT NULL,worker_id TEXT,claimed_at REAL)')
    return c

@app.post('/tasks/{task_id}/claim')
def claim(task_id: str, body: Claim):
    c = conn()
    try:
        c.execute('BEGIN IMMEDIATE')
        row = c.execute('SELECT status, worker_id FROM tasks WHERE id=?', (task_id,)).fetchone()
        if row is None:
            raise HTTPException(404, 'task not found')
        if row['status'] != 'queued':
            c.execute('ROLLBACK')
            raise HTTPException(409, f"already {row['status']} by {row['worker_id']}")
        c.execute('UPDATE tasks SET status=?,worker_id=?,claimed_at=? WHERE id=? AND status=?', ('running', body.worker_id, time.time(), task_id, 'queued'))
        if c.total_changes != 1:
            c.execute('ROLLBACK')
            raise HTTPException(409, 'claim lost race')
        c.execute('COMMIT')
        return {'task_id': task_id, 'status': 'running', 'worker_id': body.worker_id}
    except HTTPException:
        raise
    except Exception:
        try: c.execute('ROLLBACK')
        except Exception: pass
        raise
    finally:
        c.close()
